    bn_info_titel: 'Was bedeutet „Stammbaum anlegen"?',
    bn_info: 'Ein Stammbaum ist eine eigene Familienlinie – meist eine Familie mit demselben Nachnamen. Legst du hier einen neuen Stammbaum an, entsteht ein komplett eigener Baum: Du wirst sein Eigentümer und kannst Personen hinzufügen, bearbeiten und verwalten. Der neue Baum ist unabhängig von bestehenden Bäumen, bleibt aber mit deinem Familien-Verbund verknüpft – so bleiben eingeheiratete Personen über Bäume hinweg sichtbar. Gib als Namen den Nachnamen der Familie ein. Eine erste Person ist optional und bildet den Ausgangspunkt des Baums.',
