    reg_intro_titel: 'Налог и стабло – укратко',
    reg_intro_text: 'Овим обрасцем креираш свој налог. Унеси податке свог породичног стабла (назив, држава, место, општина). „Стабло" је твоја породична линија – по правилу породично презиме. Ако ово стабло већ постоји, можеш му се придружити и затражити приступ (админ потврђује). Ако још не постоји, аутоматски се прави ново, сопствено стабло за тебе – постајеш његов власник и можеш затим додавати особе.',
