    kein_baum_text: 'Тренутно немаш ниједно породично стабло. Направи ново да започнеш.',
    abw_titel: 'Презиме „{name}" не одговара тренутном стаблу и још није додељено ниједном стаблу. Шта желиш да урадиш?',
    abw_hilfe_titel: 'Зашто ово питање?',
    abw_hilfe_text: 'У овој апликацији свако стабло представља породичну линију са једним презименом. Управо додата или измењена особа носи друго презиме од овог стабла – типично код особа које су се удале/ожениле у породицу. Изабери доле како даље. Ако ниси сигуран, „Не ради ништа" је безбедно: особа остаје сачувана и повезивање можеш обавити касније у било ком тренутку.',
