    bn_info: 'Стабло је сопствена породична линија – обично породица истог презимена. Ако овде направиш ново стабло, настаје потпуно засебно стабло: постајеш његов власник и можеш додавати, уређивати и управљати особама. Ново стабло је независно од постојећих, али остаје повезано са твојим породичним савезом – тако удате/ожењене особе остају видљиве кроз више стабала. Као назив унеси породично презиме. Прва особа је опциона и чини полазну тачку стабла.',
