    reg_intro_titel: 'Nalog i stablo – ukratko',
    reg_intro_text: 'Ovim obrascem kreiraš svoj nalog. Unesi podatke svog porodičnog stabla (naziv, država, mjesto, općina). „Stablo" je tvoja porodična linija – po pravilu porodično prezime. Ako ovo stablo već postoji, možeš mu se pridružiti i zatražiti pristup (administrator potvrđuje). Ako još ne postoji, automatski se kreira novo, vlastito stablo za tebe – postaješ njegov vlasnik i možeš zatim dodavati osobe.',
