      <p>Einzelne Dienstleister können Daten außerhalb der EU (z. B. USA) verarbeiten. Die Übermittlung wird – soweit erforderlich – auf EU-Standardvertragsklauseln gestützt. [PLATZHALTER: gewählte Serverregion prüfen]</p>
